#include "obs_time.h"

#include "board.h"

void obs_time_init(void)
{
    /*
     * RTC initialization is generated by CubeMX.
     * This module only provides UTC read/write helpers.
     */
}

bool obs_time_get_utc(obs_utc_t *time)
{
    RTC_TimeTypeDef rtc_time;
    RTC_DateTypeDef rtc_date;

    if (time == NULL) {
        return false;
    }

    if (HAL_RTC_GetTime(
            &hrtc,
            &rtc_time,
            RTC_FORMAT_BIN) != HAL_OK) {
        return false;
    }

    /*
     * STM32 RTC requires a date read after time read
     * to unlock shadow registers.
     */
    if (HAL_RTC_GetDate(
            &hrtc,
            &rtc_date,
            RTC_FORMAT_BIN) != HAL_OK) {
        return false;
    }

    time->year =
        (uint16_t)(2000U + rtc_date.Year);

    time->month = rtc_date.Month;
    time->date = rtc_date.Date;
    time->weekday = rtc_date.WeekDay;

    time->hour = rtc_time.Hours;
    time->minute = rtc_time.Minutes;
    time->second = rtc_time.Seconds;

    if (rtc_time.SecondFraction > 0U) {
        time->ms =
            (uint16_t)(
                ((uint64_t)(
                    rtc_time.SecondFraction -
                    rtc_time.SubSeconds) *
                 1000ULL) /
                (rtc_time.SecondFraction + 1ULL));
    } else {
        time->ms = 0U;
    }

    return true;
}

bool obs_time_set_utc(const obs_utc_t *time)
{
    RTC_TimeTypeDef rtc_time = {0};
    RTC_DateTypeDef rtc_date = {0};

    if (
        time == NULL ||
        time->year < 2000U ||
        time->year > 2099U) {
        return false;
    }

    rtc_time.Hours = time->hour;
    rtc_time.Minutes = time->minute;
    rtc_time.Seconds = time->second;

    rtc_date.Year =
        (uint8_t)(time->year - 2000U);

    rtc_date.Month = time->month;
    rtc_date.Date = time->date;

    rtc_date.WeekDay =
        (time->weekday != 0U)
            ? time->weekday
            : RTC_WEEKDAY_MONDAY;

    if (HAL_RTC_SetTime(
            &hrtc,
            &rtc_time,
            RTC_FORMAT_BIN) != HAL_OK) {
        return false;
    }

    if (HAL_RTC_SetDate(
            &hrtc,
            &rtc_date,
            RTC_FORMAT_BIN) != HAL_OK) {
        return false;
    }

    return true;
}

uint64_t obs_time_now_us_utc(void)
{
    /*
     * Monotonic microsecond helper.
     *
     * Absolute date/time is carried separately through the RTC.
     * HAL_GetTick() currently gives millisecond source resolution.
     */
    return (uint64_t)HAL_GetTick() * 1000ULL;
}
